    40→#include "version.h"
    41→#include "ujson.h"
    42→
    43→/* objToJSON */
    44→PyObject* objToJSON(PyObject* self, PyObject *args, PyObject *kwargs);
    45→
    46→/* JSONToObj */
    47→PyObject* JSONToObj(PyObject* self, PyObject *args, PyObject *kwargs);
    48→
    49→/* objToJSONFile */
    50→PyObject* objToJSONFile(PyObject* self, PyObject *args, PyObject *kwargs);
    51→
    52→/* JSONFileToObj */
    53→PyObject* JSONFileToObj(PyObject* self, PyObject *args, PyObject *kwargs);
    54→
    55→PyObject* JSONDecodeError;
