    57→
    58→#define ENCODER_HELP_TEXT "Use ensure_ascii=false to output UTF-8. " \
    59→    "Set encode_html_chars=True to encode < > & as unicode escape sequences. "\
    60→    "Set escape_forward_slashes=False to prevent escaping / characters." \
    61→    "Set allow_nan=False to raise an exception when NaN or Infinity would be serialized." \
    62→    "Set reject_bytes=True to raise TypeError on bytes."
    63→
    64→static PyMethodDef ujsonMethods[] = {
    65→  {"encode", (PyCFunction) objToJSON, METH_VARARGS | METH_KEYWORDS, "Converts arbitrary object recursively into JSON. " ENCODER_HELP_TEXT},
    66→  {"decode", (PyCFunction) JSONToObj, METH_VARARGS | METH_KEYWORDS, "Converts JSON as string to dict object structure."},
    67→  {"dumps", (PyCFunction) objToJSON, METH_VARARGS | METH_KEYWORDS,  "Converts arbitrary object recursively into JSON. " ENCODER_HELP_TEXT},
    68→  {"loads", (PyCFunction) JSONToObj, METH_VARARGS | METH_KEYWORDS,  "Converts JSON as string to dict object structure."},
    69→  {"dump", (PyCFunction) objToJSONFile, METH_VARARGS | METH_KEYWORDS, "Converts arbitrary object recursively into JSON file. " ENCODER_HELP_TEXT},
    70→  {"load", (PyCFunction) JSONFileToObj, METH_VARARGS | METH_KEYWORDS, "Converts JSON as file to dict object structure."},
    71→  {NULL, NULL, 0, NULL}       /* Sentinel */
    72→};
    73→
    74→typedef struct {
    75→  PyObject *type_decimal;
    76→} modulestate;
    77→
    78→static int module_traverse(PyObject *m, visitproc visit, void *arg);
    79→static int module_clear(PyObject *m);
    80→static void module_free(void *m);
    81→
    82→static struct PyModuleDef moduledef = {
    83→  PyModuleDef_HEAD_INIT,
    84→  "ujson",
    85→  0,                    /* m_doc */
    86→  sizeof(modulestate),  /* m_size */
    87→  ujsonMethods,         /* m_methods */
    88→  NULL,                 /* m_slots */
    89→  module_traverse,      /* m_traverse */
    90→  module_clear,         /* m_clear */
    91→  module_free           /* m_free */
    92→};
    93→
    94→#define modulestate(o) ((modulestate *)PyModule_GetState(o))
    95→#define modulestate_global modulestate(PyState_FindModule(&moduledef))
    96→
    97→#ifndef PYPY_VERSION
    98→/* Used in objToJSON.c */
    99→int object_is_decimal_type(PyObject *obj)
   100→{
   101→  PyObject *module = PyState_FindModule(&moduledef);
   102→  if (module == NULL) return 0;
   103→  modulestate *state = modulestate(module);
   104→  if (state == NULL) return 0;
   105→  PyObject *type_decimal = state->type_decimal;
   106→  if (type_decimal == NULL) {
   107→    PyErr_Clear();
   108→    return 0;
   109→  }
   110→  int result = PyObject_IsInstance(obj, type_decimal);
   111→  if (result == -1) {
   112→    PyErr_Clear();
   113→    return 0;
   114→  }
   115→  return result;
   116→}
   117→#else
   118→/* Used in objToJSON.c */
   119→int object_is_decimal_type(PyObject *obj)
   120→{
   121→  PyObject *module = PyImport_ImportModule("decimal");
   122→  if (module == NULL) {
   123→    PyErr_Clear();
   124→    return 0;
   125→  }
   126→  PyObject *type_decimal = PyObject_GetAttrString(module, "Decimal");
   127→  if (type_decimal == NULL) {
   128→    Py_DECREF(module);
   129→    PyErr_Clear();
   130→    return 0;
   131→  }
   132→  int result = PyObject_IsInstance(obj, type_decimal);
   133→  if (result == -1) {
   134→    Py_DECREF(module);
   135→    Py_DECREF(type_decimal);
   136→    PyErr_Clear();
   137→    return 0;
   138→  }
   139→  return result;
   140→}
   141→#endif
   142→
   143→static int module_traverse(PyObject *m, visitproc visit, void *arg)
   144→{
   145→  Py_VISIT(modulestate(m)->type_decimal);
   146→  return 0;
   147→}
   148→
   149→static int module_clear(PyObject *m)
   150→{
   151→  Py_CLEAR(modulestate(m)->type_decimal);
   152→  return 0;
   153→}
   154→
   155→static void module_free(void *m)
   156→{
   157→  module_clear((PyObject *)m);
   158→}
   159→
   160→PyMODINIT_FUNC PyInit_ujson(void)
   161→{
   162→  PyObject* module;
   163→
   164→#ifndef PYPY_VERSION
   165→  // This function is not supported in PyPy.
   166→  if ((module = PyState_FindModule(&moduledef)) != NULL)
   167→  {
   168→    Py_INCREF(module);
   169→    return module;
   170→  }
   171→#endif
   172→
   173→  module = PyModule_Create(&moduledef);
   174→  if (module == NULL)
   175→  {
   176→    return NULL;
   177→  }
   178→
   179→  PyModule_AddStringConstant(module, "__version__", UJSON_VERSION);
   180→
   181→#ifndef PYPY_VERSION
   182→  PyObject *mod_decimal = PyImport_ImportModule("decimal");
   183→  if (mod_decimal)
   184→  {
   185→    PyObject* type_decimal = PyObject_GetAttrString(mod_decimal, "Decimal");
   186→    assert(type_decimal != NULL);
   187→    modulestate(module)->type_decimal = type_decimal;
   188→    Py_DECREF(mod_decimal);
   189→  }
   190→  else
   191→    PyErr_Clear();
   192→#endif
   193→
   194→  JSONDecodeError = PyErr_NewException("ujson.JSONDecodeError", PyExc_ValueError, NULL);
   195→  Py_XINCREF(JSONDecodeError);
   196→  if (PyModule_AddObject(module, "JSONDecodeError", JSONDecodeError) < 0)
   197→  {
   198→    Py_XDECREF(JSONDecodeError);
   199→    Py_CLEAR(JSONDecodeError);
   200→    Py_DECREF(module);
   201→    return NULL;
   202→  }
   203→
   204→  return module;
   205→}
